def numDecodings(s: str) -> int:
    MOD = 10 ** 9 + 7
    n = len(s)
    if not s: return 1

    # dp[i]: number of ways to parse s[:i]
    a, b = 1, 0  # a = dp[i-2], b = dp[i-1]
    # Initialization for dp[1]
    if s[0] == '*':
        b = 9
    elif s[0] != '0':
        b = 1
    else:
        b = 0

    for i in range(1, n):
        c = 0
        # Single character
        if s[i] == '*':
            c = 9 * b
        elif s[i] != '0':
            c = b
        # Two character
        if s[i-1] == '*' and s[i] == '*':
            # '*' can be '1' or '2'
            c += 15 * a  # '11'-'19' (9) + '21'-'26' (6)
        elif s[i-1] == '*':
            # s[i-1] == '*', s[i] is a digit
            if '0' <= s[i] <= '6':
                c += 2 * a  # '1x' and '2x'
            elif '7' <= s[i] <= '9':
                c += a      # only '1x'
        elif s[i] == '*':
            if s[i-1] == '1':
                c += 9 * a  # '11'-'19'
            elif s[i-1] == '2':
                c += 6 * a  # '21'-'26'
        else:
            two = int(s[i-1:i+1])
            if 10 <= two <= 26:
                c += a
        c %= MOD
        a, b = b, c
    return b
